// Generate a valid USB endpoint address: bits [3:0]=endpoint number (0..15), bit7=direction (0=OUT,1=IN)
uint8_t num = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x0F);
int dir_bit = (int)(*FUZZ_PARAM(unsigned int) & 0x01); // 0 -> OUT, 1 -> IN
uint8_t addr = (uint8_t)(num | (dir_bit ? 0x80 : 0x00));

// Invoke target and assert it decodes bit7 correctly
// Requirement enforced: only bit7 is used for direction; address constructed per spec
// Expected property: direction matches encoded bit7
{
  tusb_dir_t got = tu_edpt_dir(addr);
  if (dir_bit) {
    FUZZ_ASSERT(got == TUSB_DIR_IN, "tu_edpt_dir should return IN when bit7 is set");
  } else {
    FUZZ_ASSERT(got == TUSB_DIR_OUT, "tu_edpt_dir should return OUT when bit7 is clear");
  }
}

// Validation: The stub constructs a spec-compliant endpoint address and checks returned direction matches bit7.

// Construct a valid endpoint address: num in [0,15], dir bit random
uint8_t num = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x0F);
int dir_bit = (int)(*FUZZ_PARAM(unsigned int) & 0x01);
uint8_t addr = (uint8_t)(num | (dir_bit ? 0x80 : 0x00));

// Invoke target and assert it extracts the ep number in [0,15]
uint8_t got = tu_edpt_number(addr);
FUZZ_ASSERT(got <= 15, "tu_edpt_number must be within [0,15]");
FUZZ_ASSERT(got == num, "tu_edpt_number should equal the low 4 bits of the address");

// Validation: The stub ensures a spec-compliant address and verifies number extraction and range.

// Prepare valid inputs per requirements
uint8_t num = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x0F); // [0,15]
int dir_bit = (int)(*FUZZ_PARAM(unsigned int) & 0x01);     // 0=OUT,1=IN

// Map to tusb_dir_t domain strictly
tusb_dir_t dir = dir_bit ? TUSB_DIR_IN : TUSB_DIR_OUT;

// Invoke target
uint8_t addr = tu_edpt_addr(num, dir);

// Validate the constructed address round-trips via helper decoders
FUZZ_ASSERT(tu_edpt_number(addr) == num, "tu_edpt_addr must encode the endpoint number in bits [3:0]");
FUZZ_ASSERT((tu_edpt_dir(addr) == TUSB_DIR_IN) == (dir == TUSB_DIR_IN), "tu_edpt_addr must encode direction in bit7");

// Secondary property: ensure no other bits affect number/dir decoding
uint8_t masked = (uint8_t)((addr & 0x8F));
FUZZ_ASSERT(tu_edpt_number(masked) == num, "endpoint number must be independent of high bits except bit7");
FUZZ_ASSERT((tu_edpt_dir(masked) == TUSB_DIR_IN) == (dir == TUSB_DIR_IN), "direction must be derived solely from bit7");

// Validation: Inputs constrained to valid ranges; asserts cover correctness of address composition and decoding.

// Build a well-formed endpoint descriptor with plausible fields
// Only wMaxPacketSize is relevant for this API; others set to benign values.
tusb_desc_endpoint_t desc = {};
// Randomize endpoint number and direction fields for diversity
uint8_t ep_num = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x0F);
int dir_bit = (int)(*FUZZ_PARAM(unsigned int) & 0x01);
desc.bLength = sizeof(tusb_desc_endpoint_t);
desc.bDescriptorType = 0x05; // ENDPOINT descriptor type per USB spec
desc.bEndpointAddress = (uint8_t)(ep_num | (dir_bit ? 0x80 : 0x00));
// Randomize bmAttributes fields within their bit widths
{
  uint8_t x = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x03);
  uint8_t s = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x03);
  uint8_t u = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x03);
  desc.bmAttributes.xfer = x;
  desc.bmAttributes.sync = s;
  desc.bmAttributes.usage = u;
}
// Generate a random 16-bit wMaxPacketSize; API will mask to 11 bits
uint16_t raw_mps = *FUZZ_PARAM(uint16_t);
desc.wMaxPacketSize = raw_mps;
// Polling interval arbitrary
desc.bInterval = (uint8_t)*FUZZ_PARAM(unsigned int);

// Invoke target
uint16_t ps = tu_edpt_packet_size(&desc);

// Enforce requirement: only lower 11 bits are returned
FUZZ_ASSERT(ps <= 0x07FF, "tu_edpt_packet_size must return <= 0x7FF");

// Optional consistency: if raw_mps already within 11 bits, expect equality
if ((raw_mps & 0xF800u) == 0) {
  FUZZ_ASSERT(ps == (raw_mps & 0x07FFu), "tu_edpt_packet_size should equal raw value when high bits clear");
}

// Validation: Non-null, initialized descriptor is provided; result range is asserted and consistent with masking behavior.

// Exercise tu_memset_s with valid, zero-count, and overflow cases while respecting constraints.
// Generate destination size (0..1023) and fill value
size_t destsz = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
int ch = (int)(*FUZZ_PARAM(unsigned int) & 0xFF);
// Choose count in [0, destsz+1] to cover success and failure paths
size_t count_choice = (size_t)(*FUZZ_PARAM(unsigned int) % (destsz + 2));

// Prepare destination buffer; if destsz == 0 we will use nullptr for zero-count case
std::vector<uint8_t> dest_buf(destsz ? destsz : 1, 0xAA);
void* dest_ptr = destsz ? (void*)dest_buf.data() : nullptr;

if (count_choice == 0) {
  // count == 0 must succeed even with NULL dest
  int rc0 = tu_memset_s(nullptr, 0, ch, 0);
  FUZZ_ASSERT(rc0 == 0, "tu_memset_s(count==0) must return 0");
} else if (count_choice > destsz) {
  // count > destsz must fail and not write
  uint8_t before0 = destsz ? dest_buf[0] : 0xAA;
  int rc = tu_memset_s(dest_ptr, destsz, ch, count_choice);
  FUZZ_ASSERT(rc == -1, "tu_memset_s must fail when count > destsz");
  if (destsz) { FUZZ_ASSERT(dest_buf[0] == before0, "tu_memset_s must not write on failure"); }
} else {
  // Valid case: count <= destsz and dest non-NULL
  if (!dest_ptr) { FUZZ_BAIL(); }
  int rc = tu_memset_s(dest_ptr, destsz, ch, count_choice);
  FUZZ_ASSERT(rc == 0, "tu_memset_s valid params must succeed");
  for (size_t i = 0; i < count_choice; i++) {
    FUZZ_ASSERT(dest_buf[i] == (uint8_t)ch, "tu_memset_s must set requested bytes");
  }
}

// Exercise tu_memcpy_s: zero-count, overflow, and valid copy without overlap.
size_t destsz = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
size_t max_count = destsz + 2; // allow overflow path
size_t count_choice = (size_t)(*FUZZ_PARAM(unsigned int) % (max_count + 1));

// Prepare separate source and destination buffers to avoid overlap
std::vector<uint8_t> dest_buf(destsz ? destsz : 1, 0xDD);
std::vector<uint8_t> src_buf;
size_t src_needed = count_choice; // number of readable bytes required when count>0
if (src_needed > 0) {
  size_t srcsz = std::max((size_t)1, src_needed);
  src_buf.resize(srcsz);
  // Fill src with deterministic fuzz data
  std::string rand = FUZZ_PARAM_STR();
  for (size_t i = 0; i < srcsz; i++) src_buf[i] = (uint8_t)rand[i % rand.size()];
}

if (count_choice == 0) {
  int rc0 = tu_memcpy_s(nullptr, 0, nullptr, 0);
  FUZZ_ASSERT(rc0 == 0, "tu_memcpy_s(count==0) must return 0");
} else if (count_choice > destsz) {
  uint8_t before0 = destsz ? dest_buf[0] : 0xDD;
  int rc = tu_memcpy_s(destsz ? (void*)dest_buf.data() : nullptr, destsz, src_buf.data(), count_choice);
  FUZZ_ASSERT(rc == -1, "tu_memcpy_s must fail when count > destsz");
  if (destsz) { FUZZ_ASSERT(dest_buf[0] == before0, "tu_memcpy_s must not write on failure"); }
} else {
  if (!destsz) { FUZZ_BAIL(); }
  // Valid copy: count_choice in [1, destsz]
  int rc = tu_memcpy_s(dest_buf.data(), destsz, src_buf.data(), count_choice);
  FUZZ_ASSERT(rc == 0, "tu_memcpy_s valid params must succeed");
  for (size_t i = 0; i < count_choice; i++) {
    FUZZ_ASSERT(dest_buf[i] == src_buf[i], "tu_memcpy_s must copy bytes");
  }
}

// Validate tu_mem_is_zero behavior for zero and non-zero buffers.
size_t size = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
std::vector<uint8_t> buf(size ? size : 1, 0x00);
bool make_zero = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
if (!make_zero && size > 0) {
  // Ensure at least one non-zero byte
  buf[0] = (uint8_t)((*FUZZ_PARAM(unsigned int) & 0xFF) | 1);
}
bool res = tu_mem_is_zero(buf.data(), size);
bool expect = (size == 0) ? true : make_zero;
FUZZ_ASSERT(res == expect, "tu_mem_is_zero must reflect whether buffer is all zeros");

// Validate tu_mem_is_ff behavior for all-0xFF and mixed buffers.
size_t size = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
std::vector<uint8_t> buf(size ? size : 1, 0xFF);
bool make_ff = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
if (!make_ff && size > 0) {
  buf[0] = 0x00; // ensure not all 0xFF
}
bool res = tu_mem_is_ff(buf.data(), size);
bool expect = (size == 0) ? true : make_ff;
FUZZ_ASSERT(res == expect, "tu_mem_is_ff must reflect whether buffer is all 0xFF");

// Validate tu_u32 byte packing (big-endian byte order for parameters b3..b0).
uint8_t b3 = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
uint8_t b2 = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
uint8_t b1 = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
uint8_t b0 = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
uint32_t got = tu_u32(b3, b2, b1, b0);
uint32_t expect = ((uint32_t)b3 << 24) | ((uint32_t)b2 << 16) | ((uint32_t)b1 << 8) | (uint32_t)b0;
FUZZ_ASSERT(got == expect, "tu_u32 must pack bytes into 32-bit value");

// Validate tu_u32_from_u16 packing high and low 16-bit halves.
uint16_t hi = (uint16_t)(*FUZZ_PARAM(unsigned int) & 0xFFFF);
uint16_t lo = (uint16_t)(*FUZZ_PARAM(unsigned int) & 0xFFFF);
uint32_t got = tu_u32_from_u16(hi, lo);
uint32_t expect = ((uint32_t)hi << 16) | (uint32_t)lo;
FUZZ_ASSERT(got == expect, "tu_u32_from_u16 must pack high/low halves");

// Validate tu_u16 packing high and low bytes.
uint8_t hi = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
uint8_t lo = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
uint16_t got = tu_u16(hi, lo);
uint16_t expect = ((uint16_t)hi << 8) | (uint16_t)lo;
FUZZ_ASSERT(got == expect, "tu_u16 must pack bytes into 16-bit value");

// Validate tu_u32_byte3 extracts MSB.
uint32_t v = *FUZZ_PARAM(unsigned int);
uint8_t got = tu_u32_byte3(v);
uint8_t expect = (uint8_t)((v >> 24) & 0xFF);
FUZZ_ASSERT(got == expect, "tu_u32_byte3 must return MSB");

// Validate tu_u32_byte2 extracts byte 2.
uint32_t v = *FUZZ_PARAM(unsigned int);
uint8_t got = tu_u32_byte2(v);
uint8_t expect = (uint8_t)((v >> 16) & 0xFF);
FUZZ_ASSERT(got == expect, "tu_u32_byte2 must return byte2");

// Validate tu_u32_byte1 extracts byte 1.
uint32_t v = *FUZZ_PARAM(unsigned int);
uint8_t got = tu_u32_byte1(v);
uint8_t expect = (uint8_t)((v >> 8) & 0xFF);
FUZZ_ASSERT(got == expect, "tu_u32_byte1 must return byte1");

// Validate tu_u32_byte0 extracts LSB.
uint32_t v = *FUZZ_PARAM(unsigned int);
uint8_t got = tu_u32_byte0(v);
uint8_t expect = (uint8_t)(v & 0xFF);
FUZZ_ASSERT(got == expect, "tu_u32_byte0 must return LSB");

// Validate tu_u32_high16 extracts upper 16 bits.
uint32_t v = *FUZZ_PARAM(unsigned int);
uint16_t got = tu_u32_high16(v);
uint16_t expect = (uint16_t)((v >> 16) & 0xFFFF);
FUZZ_ASSERT(got == expect, "tu_u32_high16 must return high 16 bits");

// Validate tu_u32_low16 extracts lower 16 bits.
uint32_t v = *FUZZ_PARAM(unsigned int);
uint16_t got = tu_u32_low16(v);
uint16_t expect = (uint16_t)(v & 0xFFFF);
FUZZ_ASSERT(got == expect, "tu_u32_low16 must return low 16 bits");

// Validate tu_u16_high extracts high byte.
uint16_t v = (uint16_t)(*FUZZ_PARAM(unsigned int) & 0xFFFF);
uint8_t got = tu_u16_high(v);
uint8_t expect = (uint8_t)((v >> 8) & 0xFF);
FUZZ_ASSERT(got == expect, "tu_u16_high must return high byte");

// Validate tu_u16_low extracts low byte.
uint16_t v = (uint16_t)(*FUZZ_PARAM(unsigned int) & 0xFFFF);
uint8_t got = tu_u16_low(v);
uint8_t expect = (uint8_t)(v & 0xFF);
FUZZ_ASSERT(got == expect, "tu_u16_low must return low byte");
// Validation: Confirms low-byte extraction against bitmask computation.

// Validate tu_bit_set sets the specified bit (0..31).
uint32_t value = *FUZZ_PARAM(unsigned int);
uint8_t pos = (uint8_t)(*FUZZ_PARAM(unsigned int) % 32);
uint32_t got = tu_bit_set(value, pos);
uint32_t expect = value | (1UL << pos);
FUZZ_ASSERT(got == expect, "tu_bit_set must set the target bit to 1");
// Validation: Ensures bitwise OR with single-bit mask behavior.

// Validate tu_bit_clear clears the specified bit (0..31).
uint32_t value = *FUZZ_PARAM(unsigned int);
uint8_t pos = (uint8_t)(*FUZZ_PARAM(unsigned int) % 32);
uint32_t got = tu_bit_clear(value, pos);
uint32_t expect = value & ~(1UL << pos);
